// Keep this file as the single source of truth for i18n keys & strings.

export type Locale = "fr" | "en" | "de" | "es" | "it" | "pt" | "tr" | "pl";

export interface LocaleInfo {
  code: Locale;
  label: string;
  flag: string;
}

export const LOCALES: LocaleInfo[] = [
  { code: "fr", label: "Français", flag: "🇫🇷" },
  { code: "en", label: "English", flag: "🇬🇧" },
  { code: "de", label: "Deutsch", flag: "🇩🇪" },
  { code: "es", label: "Español", flag: "🇪🇸" },
  { code: "it", label: "Italiano", flag: "🇮🇹" },
  { code: "pt", label: "Português", flag: "🇵🇹" },
  { code: "tr", label: "Türkçe", flag: "🇹🇷" },
  { code: "pl", label: "Polski", flag: "🇵🇱" },
];

/**
 * Les clés sont dérivées du dictionnaire français (texte source + fallback).
 * Ajouter une clé = l'ajouter dans `fr` **et** dans les 7 autres dictionnaires
 * (le test `translations.test.ts` vérifie la parité).
 */
export type TranslationKeys = keyof typeof fr;
type Dictionary = Record<TranslationKeys, string>;

